'use strict';
window.OrionI18n=(()=>{const key='orion-expedition-language';let lang='en';try{const saved=localStorage.getItem(key);lang=['en','zh-Hant'].includes(saved)?saved:(navigator.language.toLowerCase().startsWith('zh')?'zh-Hant':'en');}catch{}const t=(en,zh)=>lang==='en'?en:zh;function apply(){document.documentElement.lang=lang;document.querySelectorAll('[data-en]').forEach(el=>{const value=el.getAttribute(lang==='en'?'data-en':'data-zh');const attr=el.getAttribute('data-i18n-attr');if(attr)el.setAttribute(attr,value);else el.innerHTML=value;});const select=document.getElementById('language');if(select)select.value=lang;window.dispatchEvent(new Event('orion-language'));}function set(value){if(!['en','zh-Hant'].includes(value))return;lang=value;try{localStorage.setItem(key,lang);}catch{}apply();}window.addEventListener('storage',e=>{if(e.key===key&&['en','zh-Hant'].includes(e.newValue)){lang=e.newValue;apply();}});window.addEventListener('pageshow',()=>{try{const saved=localStorage.getItem(key);if(['en','zh-Hant'].includes(saved))lang=saved;}catch{}apply();});document.getElementById('language')?.addEventListener('change',e=>set(e.target.value));return{t,apply,set,get lang(){return lang;}};})();
